using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "Draw", menuName = "Data/Battle/Battle Actions/Tactical Actions/Draw Action")]
public class DrawAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private PlayerDiceInventoryData diceBag;

	[SerializeField]
	private PlayerDiceInventoryData discard;

	[SerializeField]
	private bool drawSpecificTier;

	[SerializeField]
	[ShowIf("drawSpecificTier")]
	private DiceTier diceSpecificTier;

	[SerializeField]
	private bool drawSpecificTierRandom;

	[SerializeField]
	[ShowIf("drawSpecificTierRandom")]
	private DiceTier[] diceSpecificTiers;

	[SerializeField]
	private bool drawSpecificDice;

	[SerializeField]
	[ShowIf("drawSpecificDice")]
	private string specificDiceName;

	[SerializeField]
	private bool drawSpecificDiceType;

	[SerializeField]
	[ShowIf("drawSpecificDiceType")]
	private string specificDiceTypeName;

	[SerializeField]
	private bool drawBasedOnEffect;

	[SerializeField]
	[ShowIf("drawBasedOnEffect")]
	private Effect effect;

	[SerializeField]
	[ShowIf("drawBasedOnEffect")]
	private float drawAmountBasedOnEffectMultiplier;

	[SerializeField]
	[ShowIf("drawBasedOnEffect")]
	private int decreaseEffectAmount;

	[SerializeField]
	[ShowIf("drawBasedOnEffect")]
	private int drawBasedOnEffectBaseDrawAmount;

	[SerializeField]
	private bool drawUntilHandIsFull;

	[SerializeField]
	private bool drawMagnitezedDice;

	[SerializeField]
	private bool drawDiscard;

	[SerializeField]
	private bool extraAction;

	[SerializeField]
	[ShowIf("extraAction")]
	private OmenLogicActionFace extraActionOmenLogicActionFace;

	[Header("Spectral Harvester")]
	[SerializeField]
	private bool spectralHarvesterDraw;

	[Header("Sages Card")]
	[SerializeField]
	private bool sagesCardDrawDraw;

	[Header("Debug")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	protected bool verbose;

	public DiceTier DiceSpecificTier => diceSpecificTier;

	public int DrawAmountBasedOnEffectDivider => Mathf.CeilToInt(1f / drawAmountBasedOnEffectMultiplier);

	public int DecreaseEffectAmount => decreaseEffectAmount;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (drawBasedOnEffect && GetDrawAmountBasedOnEffect() == 0)
		{
			return false;
		}
		if (drawSpecificTierRandom)
		{
			for (int i = 0; i < diceSpecificTiers.Length; i++)
			{
				List<Dice> allDiceFromSpecificTier = diceBag.GetAllDiceFromSpecificTier(diceSpecificTiers[i]);
				List<Dice> allDiceFromSpecificTier2 = discard.GetAllDiceFromSpecificTier(diceSpecificTiers[i]);
				if (allDiceFromSpecificTier.Count > 0 || allDiceFromSpecificTier2.Count > 0)
				{
					return true;
				}
			}
			return false;
		}
		if (drawSpecificTier)
		{
			List<Dice> allDiceFromSpecificTier3 = diceBag.GetAllDiceFromSpecificTier(diceSpecificTier);
			List<Dice> allDiceFromSpecificTier4 = discard.GetAllDiceFromSpecificTier(diceSpecificTier);
			if (allDiceFromSpecificTier3.Count <= 0)
			{
				return allDiceFromSpecificTier4.Count > 0;
			}
			return true;
		}
		if (drawSpecificDice)
		{
			List<Dice> specificDice = diceBag.GetSpecificDice(specificDiceName);
			List<Dice> specificDice2 = discard.GetSpecificDice(specificDiceName);
			if (specificDice.Count <= 0)
			{
				return specificDice2.Count > 0;
			}
			return true;
		}
		if (drawSpecificDiceType)
		{
			List<Dice> specificDiceType = diceBag.GetSpecificDiceType(specificDiceTypeName);
			List<Dice> specificDiceType2 = discard.GetSpecificDiceType(specificDiceTypeName);
			if (specificDiceType.Count <= 0)
			{
				return specificDiceType2.Count > 0;
			}
			return true;
		}
		if (drawDiscard)
		{
			return discard.GetDicesAmount() > 0;
		}
		if (diceBag.GetDicesAmount() <= 0)
		{
			return discard.GetDicesAmount() > 0;
		}
		return true;
	}

	public int GetDrawAmountBasedOnEffect()
	{
		return Mathf.FloorToInt((float)ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().IsEffectActiveGetAmount(effect, activateFeedback: false) * drawAmountBasedOnEffectMultiplier) + drawBasedOnEffectBaseDrawAmount;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		if (CheckImmobilized(source))
		{
			return;
		}
		if (!CheckConditionToBeCasted(playerHand: false, DiceOwnerEnum.PLAYER))
		{
			ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
			return;
		}
		if (drawSpecificTierRandom)
		{
			List<DiceTier> list = diceSpecificTiers.DuplicateAsList();
			list.Shuffle();
			for (int i = 0; i < list.Count; i++)
			{
				List<Dice> allDiceFromSpecificTier = diceBag.GetAllDiceFromSpecificTier(list[i]);
				List<Dice> allDiceFromSpecificTier2 = discard.GetAllDiceFromSpecificTier(list[i]);
				if (allDiceFromSpecificTier.Count > 0 || allDiceFromSpecificTier2.Count > 0)
				{
					DrawSpecificDiceTier(amount, list[i], source);
					break;
				}
			}
		}
		else if (drawSpecificTier)
		{
			DrawSpecificDiceTier(amount, diceSpecificTier, source);
		}
		else if (drawSpecificDice)
		{
			DrawSpecificDice(amount, source);
		}
		else if (drawSpecificDiceType)
		{
			DrawSpecificDiceType(amount, source);
		}
		else if (drawDiscard)
		{
			DrawFromDiscard(amount, source);
		}
		else
		{
			ReferenceSingleton<DiceDrawingHandler>.Instance.DrawActionCast(amount);
		}
		$"DRAW ACTION: Drawing {amount.ToString()} dice".DebugLogIfVerbose(verbose);
	}

	private bool CheckImmobilized(GameObject source)
	{
		if (!ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
		{
			return false;
		}
		if (ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerImmobilized())
		{
			ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
			return true;
		}
		return false;
	}

	public override void Cast(GameObject source)
	{
		if (CheckImmobilized(source))
		{
			return;
		}
		int amount = 0;
		if (drawUntilHandIsFull)
		{
			amount = ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.HandLimit - ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount();
		}
		else if (drawBasedOnEffect)
		{
			amount = GetDrawAmountBasedOnEffect();
			if (decreaseEffectAmount > 0)
			{
				ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().IsEffectActiveAndDecreaseEffect(effect, decreaseEffectAmount);
			}
		}
		if (drawSpecificTierRandom)
		{
			List<DiceTier> list = diceSpecificTiers.DuplicateAsList();
			list.Shuffle();
			for (int i = 0; i < list.Count; i++)
			{
				List<Dice> allDiceFromSpecificTier = diceBag.GetAllDiceFromSpecificTier(list[i]);
				List<Dice> allDiceFromSpecificTier2 = discard.GetAllDiceFromSpecificTier(list[i]);
				if (allDiceFromSpecificTier.Count > 0 || allDiceFromSpecificTier2.Count > 0)
				{
					DrawSpecificDiceTier(amount, list[i], source);
					break;
				}
			}
		}
		else if (drawSpecificTier)
		{
			DrawSpecificDiceTier(amount, diceSpecificTier, source);
		}
		else if (drawSpecificDice)
		{
			DrawSpecificDice(amount, source);
		}
		else if (drawMagnitezedDice)
		{
			DrawAllMagnetizedDice(source);
		}
		else if (drawDiscard)
		{
			DrawFromDiscard(amount, source);
		}
		else
		{
			ReferenceSingleton<DiceDrawingHandler>.Instance.DrawActionCast(amount);
		}
		$"DRAW ACTION: Drawing {amount.ToString()} dice".DebugLogIfVerbose(verbose);
	}

	private void DrawSpecificDiceTier(int amount, DiceTier diceTier, GameObject source)
	{
		DrawSpecificDice(amount, diceBag.GetAllDiceFromSpecificTier(diceTier), discard.GetAllDiceFromSpecificTier(diceTier), source);
	}

	private void DrawSpecificDice(int amount, GameObject source)
	{
		DrawSpecificDice(amount, diceBag.GetSpecificDice(specificDiceName), discard.GetSpecificDice(specificDiceName), source);
	}

	private void DrawSpecificDiceType(int amount, GameObject source)
	{
		DrawSpecificDice(amount, diceBag.GetSpecificDiceType(specificDiceTypeName), discard.GetSpecificDiceType(specificDiceTypeName), source);
	}

	private void DrawAllMagnetizedDice(GameObject source)
	{
		int amount = int.MaxValue;
		DrawSpecificDice(amount, diceBag.GetAllMagnetizedDice(), discard.GetAllMagnetizedDice(), source);
	}

	private void DrawSpecificDice(int amount, List<Dice> diceBagDice, List<Dice> discardDice, GameObject source)
	{
		if (CheckImmobilized(source))
		{
			return;
		}
		if (diceBagDice.Count > 0)
		{
			if (diceBagDice.Count >= amount)
			{
				DrawSpecificDiceFromDrawPool(diceBagDice, amount);
			}
			else if (discardDice.Count > 0)
			{
				int num = amount - diceBagDice.Count;
				new List<Dice>();
				new List<bool>();
				if (discardDice.Count >= num)
				{
					DrawSpecificDiceFromBothPools(diceBagDice, discardDice, num);
					return;
				}
				num = discardDice.Count;
				DrawSpecificDiceFromBothPools(diceBagDice, discardDice, num);
			}
			else
			{
				amount = diceBagDice.Count;
				DrawSpecificDiceFromDrawPool(diceBagDice, amount);
			}
		}
		else if (discardDice.Count > 0)
		{
			if (discardDice.Count >= amount)
			{
				DrawSpecificDiceFromDiscard(discardDice, amount);
				return;
			}
			amount = discardDice.Count;
			DrawSpecificDiceFromDiscard(discardDice, amount);
		}
		else
		{
			ReferenceSingleton<GameStateManager>.Instance.SetChooseActionState();
		}
	}

	private void DrawSpecificDiceFromDrawPool(List<Dice> dice, int amount)
	{
		List<Dice> list = dice.PopRandom(amount);
		for (int i = 0; i < list.Count; i++)
		{
			diceBag.DecreaseDiceAmount(list[i], 1);
		}
		ReferenceSingleton<DiceDrawingHandler>.Instance.DrawSpecificDiceFromSinglePool(list);
	}

	private void DrawSpecificDiceFromDiscard(List<Dice> dice, int amount)
	{
		List<Dice> list = dice.PopRandom(amount);
		for (int i = 0; i < list.Count; i++)
		{
			discard.DecreaseDiceAmount(list[i], 1);
		}
		ReferenceSingleton<DiceDrawingHandler>.Instance.DrawSpecificDiceFromSinglePool(list, drawFromDiscard: true);
	}

	private void DrawSpecificDiceFromBothPools(List<Dice> dice, List<Dice> diceFromDiscard, int diceToPickRemainingAmount)
	{
		List<Dice> list = new List<Dice>();
		List<bool> list2 = new List<bool>();
		for (int i = 0; i < dice.Count; i++)
		{
			list2.Add(item: false);
		}
		list.AddRange(dice);
		for (int j = 0; j < dice.Count; j++)
		{
			diceBag.DecreaseDiceAmount(dice[j], 1);
		}
		for (int k = 0; k < diceToPickRemainingAmount; k++)
		{
			list2.Add(item: true);
		}
		List<Dice> list3 = diceFromDiscard.PickRandom(diceToPickRemainingAmount);
		list.AddRange(list3);
		for (int l = 0; l < list3.Count; l++)
		{
			discard.DecreaseDiceAmount(list3[l], 1);
		}
		ReferenceSingleton<DiceDrawingHandler>.Instance.DrawSpecificDiceFromMoreThanOnePool(list, list2);
	}

	private void DrawFromDiscard(int amount, GameObject source)
	{
		if (!CheckImmobilized(source))
		{
			List<Dice> list = discard.GetAllDices().Duplicate().PickRandom(amount);
			for (int i = 0; i < list.Count; i++)
			{
				discard.DecreaseDiceAmount(list[i], 1);
			}
			ReferenceSingleton<DiceDrawingHandler>.Instance.DrawSpecificDiceFromSinglePool(list, drawFromDiscard: true);
		}
	}
}
